INSERT INTO `league_rulesets` VALUES (1,1,'Default Local Rules','published','{\"localRules\":[\"Mulligan on first hole played. If your first shot is not a good one you may without penalty play a second shot, with the caveat that you must play the second shot (you don\'t choose the best one).\",\"Out of Bounds. Balls hit OB can be played as one stoke penalty with no distance penalty. The ball can NOT be played from OB but the ball may be dropped as it would if the penalty area was marked with red stakes. Either two club lengths from where the ball entered the penalty area; or as far back as desired on a line from the hole to the where the ball crossed into the penalty area.\",\"Gimme\'s there are no gimme\'s during the championship. During regular season anything within 12 inches can be given. Gimme\'s must be given by a playing partner (you can\'t give yourself a putt).\"]}','2026-05-21',NULL,NULL,NULL,'2026-05-21 18:59:48','2026-05-21 18:59:48','2026-05-21 18:59:48'),(2,1,'Paradise Wednesday League Rules','draft','{\"sections\":[{\"id\":\"schedule\",\"title\":\"League Schedule & Format\",\"visible\":true,\"type\":\"text\",\"content\":\"Wednesday nights at Eagles Golf Club in Odessa\\n\\nStarting: March 18th\\nFinals: 18 hole round on September 26th\\nTee Time: Shot gun start at around 5:00 PM each week\\nCost: $25.00 league fee + $23.00 per week greens fee\"},{\"id\":\"localRules\",\"title\":\"Local Rules\",\"visible\":true,\"type\":\"list\",\"items\":[\"Mulligan on first hole played. If your first shot is not a good one you may without penalty play a second shot, with the caveat that you must play the second shot (you don\'t choose the best one).\",\"Out of Bounds. Balls hit OB can be played as one stoke penalty with no distance penalty. The ball can NOT be played from OB but the ball may be dropped as it would if the penalty area was marked with red stakes. Either two club lengths from where the ball entered the penalty area; or as far back as desired on a line from the hole to the where the ball crossed into the penalty area.\",\"Gimme\'s there are no gimme\'s during the championship. During regular season anything within 12 inches can be given. Gimme\'s must be given by a playing partner (you can\'t give yourself a putt).\",\"Note: If you start your round on a par 3 - you are NOT able to claim CTP for Mulligan shot. Also Hole in Ones are only if it is your first shot if you get a Hole in One with your mulligan shot it counts as an Eagle.\"]},{\"id\":\"quotaPoints\",\"title\":\"Quota Point System\",\"visible\":true,\"type\":\"text\",\"content\":\"The Quota Point system awards points based on your scores for each hole. Once you hit double bogey, you pick up and move to the next hole to keep pace of play.\"},{\"id\":\"costsPrizes\",\"title\":\"Costs & Prize Money\",\"visible\":true,\"type\":\"text\",\"content\":\"Required Fees:\\n$25.00 - One-time league fee for the season\\n$23.00 - Weekly greens fee (paid each week you play)\\n$3.00 - Hole-in-one/Double Eagle pool (from league fee)\\n\\nSeason Prize Distribution:\\n1st Place: 60%\\n2nd Place: 20%\\n3rd Place: 10%\\nGolf Hat & Closest to Pin: 10%\"}]}',NULL,NULL,10,NULL,NULL,'2026-07-15 16:32:02','2026-07-15 16:32:02');
/*!40000 ALTER TABLE `league_rulesets` ENABLE KEYS */;
UNLOCK TABLES;

